import{z as d,x as s,o as l,c as B,q as E,j as o,D as A,d as t,s as r,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"MLA 对 KV 的压缩","description":"","frontmatter":{"title":"MLA 对 KV 的压缩","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mla-kv.md","filePath":"llm/mla-kv.md","lastUpdated":1791413859000}'),m={name:"llm/mla-kv.md"};function p(h,a,V,c,k,K){const n=s("Mermaid");return l(),B("div",null,[a[2]||(a[2]=E('<h1 id="mla-对-kv-的压缩" tabindex="-1">MLA 对 KV 的压缩 <a class="header-anchor" href="#mla-对-kv-的压缩" aria-label="Permalink to &quot;MLA 对 KV 的压缩&quot;">​</a></h1><div class="epigraph"><p>对键值做低秩联合压缩；推理时把上投影吸收进权重，解码只需缓存压缩后的潜向量。</p><footer>—— DeepSeek-AI, DeepSeek-V2: A Strong, Economical, and Efficient Mixture-of-Experts Language Model, 2024</footer></div><p><a href="/llm/streaming-kv">上一课</a>把 \\(n_{\\mathrm{keep}}\\) 钉成汇点加窗口，缓存与生成长度脱钩，按位置留槽、中段历史精确丢失。缺口是宽度轴：条数淘汰动的是谁留下，每条仍是满宽 \\(K,V\\)；GQA 少头，MLA 则每个 token 一条窄潜向量，头数可以保持。本课钉 MLA 对 KV 的压缩：decode 缓存 \\(c^{KV}\\) 与小 RoPE 键，上投影吸收才兑现服务降幅。不重讲汇点环形缓冲。架构公式见 <a href="/llm/mla">MLA</a>；后课连续批默认每 token 字节已经按这条宽度记账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>StreamingLLM 钉的是 \\(n_{\\mathrm{keep}}\\)；每条仍可以是满宽 \\(K,V\\)。推理显存里，注意力的 KV 往往压过激活，长生成、高并发时压过一部分权重。MHA 每层每 token 存 \\(2 h d_k\\) 个数；GQA 把它变成 \\(2 h_{\\mathrm{kv}} d_k\\)。继续减 \\(h_{\\mathrm{kv}}\\) 是在砍记忆通道，质量会掉。另一条没被 GQA 用掉的自由度是：生成 \\(K,V\\) 的映射可能是低秩的，真正需要<strong>随序列增长而驻留</strong>的自由度数远小于 \\(h d_k\\)。若训练时就用瓶颈去写 KV，推理就可以只缓存瓶颈。</p><p>目标有三条同时成立。第一，训练仍按多头算分数、混值，质量对标 MHA。第二，decode 不得把满宽 \\(K,V\\) 物化进缓存。第三，RoPE 作用在头内坐标上，不能被共享潜变量直接旋转掉。压缩 KV 的设计必须回答：缓存张量的形状变成什么、每 token 多少字节、并发因此能抬多少。</p><p><span class="marginnote">KV 缓存可以类比开会纪要：模型每生成一个新词，都要回头翻前面所有词的「纪要」（键给匹配度，值给内容）。MHA 存的是每个词一整套展开的纪要，文件越攒越多；MLA 的思路是每词只存一份压缩包，开会要用时再当场解压——解压规则（上投影）烘焙在权重里，缓存里永远只有小份压缩包。</span></p><h3 id="压缩轴是宽度-不是条数" tabindex="-1">压缩轴是宽度，不是条数 <a class="header-anchor" href="#压缩轴是宽度-不是条数" aria-label="Permalink to &quot;压缩轴是宽度，不是条数&quot;">​</a></h3><p>StreamingLLM、H2O 减 \\(n_{\\mathrm{keep}}\\)；MLA 的 \\(n_{\\mathrm{keep}}\\) 仍等于序列长 \\(n\\)，包括提示和已生成。不等式里被动的是每条的宽度：</p> \\[n\\cdot (d_c + d_R)\\cdot b_{\\mathrm{bit}}\\;\\lesssim\\; B_{\\mathrm{MLA}} \\quad\\text{对}\\quad n\\cdot 2 h d_k\\cdot b_{\\mathrm{bit}}\\;=\\; B_{\\mathrm{MHA}}. \\]<p>取 V2 报告所用的量级：\\(d_c=512\\)、\\(h=128\\)、\\(d_k=128\\)、\\(d_R=64\\)。满宽 MHA 每 token 每层约 \\(2\\times 128\\times 128\\) 个数；MLA 的 \\(c^{KV}\\) 只有 \\(512\\)，外加一条跨头共享的 RoPE 键，仅 \\(d_R=64\\) 维。下降来自 \\(d_c\\ll h d_k\\)，外加 RoPE 旁路远窄于内容键。联合压缩还让 \\(K\\) 与 \\(V\\) 共享同一份 \\(c^{KV}\\)，不是各压各的。</p><p><span class="marginnote">不要把 MLA 理解成对已经生成的 MHA 缓存做 PCA。低秩是训练写路径上的瓶颈，权重按这个瓶颈补偿过。事后对 GQA 缓存做低秩近似，误差来自逼近已有激活，和 MLA 不是一类方法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对隐状态 \\(h_t\\) 先下投影 \\(c_t^{KV}=W^{DKV}h_t\\)。内容键、值由 \\(W^{UK},W^{UV}\\) 展开到多头。查询侧也可先压再展开，查询不进 decode 缓存。RoPE 走旁路：\\(q^R,k^R\\) 带旋转位置，不经过会破坏旋转结构的内容低秩路径。</p><h3 id="吸收之后缓存里到底有什么" tabindex="-1">吸收之后缓存里到底有什么 <a class="header-anchor" href="#吸收之后缓存里到底有什么" aria-label="Permalink to &quot;吸收之后缓存里到底有什么&quot;">​</a></h3><p>内容分数 \\((q^C)^\\top k^C\\) 可改写成对 \\(c^{KV}\\) 的线性型，输出侧 \\(W^O v^C\\) 同样吸收 \\(W^{UV}\\)。于是 decode 的追加物是：</p><ul><li>每层每 token 一份 \\(c^{KV}\\in\\mathbb{R}^{d_c}\\)；</li><li>每层每 token 一份未吸收的 \\(k^R\\)，是跨头共享的 \\(d_R\\) 维向量。</li></ul><p>满宽 \\(k^C,v^C\\) 是计算图里的临时量，不落 HBM 上的 KV 池。实现若「能出对的数」却每步物化满头 \\(K,V\\) 再缓存，压缩幅度会退回 MHA，V2 作为服务卖点的那一截 KV 降幅不会出现。融合发生在启动时或离线一次，不是逐步生成时现乘。</p>',18)),(l(),o(i,null,{default:A(()=>[r(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E9%9A%90%E7%8A%B6%E6%80%81%22%5D%20--%3E%20C%5B%22cKV%20%E4%B8%8B%E6%8A%95%E5%BD%B1%22%5D%0A%20%20H%20--%3E%20R%5B%22%E8%A7%A3%E8%80%A6%20RoPE%20%E9%94%AE%22%5D%0A%20%20C%20--%3E%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%B8%8A%E6%8A%95%E5%BD%B1%22%5D%0A%20%20ABS%20--%3E%20POOL%5B%22KV%20%E6%B1%A0%3A%20cKV%22%5D%0A%20%20R%20--%3E%20POOL2%5B%22KV%20%E6%B1%A0%3A%20%E5%B0%8F%20kR%22%5D%0A%20%20POOL%20--%3E%20D%5B%22decode%20%E9%80%90%E6%AD%A5%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20POOL2%20--%3E%20D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"并发与带宽账单",tabindex:"-1"},[t("并发与带宽账单 "),e("a",{class:"header-anchor",href:"#并发与带宽账单","aria-label":'Permalink to "并发与带宽账单"'},"​")],-1)),a[4]||(a[4]=e("p",null,"decode 几乎总是带宽墙：每步扫完全部已驻留 KV。每 token 字节下降，同样的 HBM 可以多放几倍并发，或同一并发下拉更长的生成。MoE 模型参数已很大、激活稀疏，KV 更容易成为墙，这也是 MLA 出现在 DeepSeek-V2 里的上下文——专家权重和 KV 抢同一块显存，压缩 KV 是在给专家和 batch 腾地方。",-1)),a[5]||(a[5]=e("p",null,"张量并行要小心。若 TP 在每张卡上复制完整的潜投影与 \\(c^{KV}\\)，省下的缓存会被复制吃回去。开源栈常见的配法是注意力（含 MLA）走数据并行复制、专家走专家并行，避免把 MLA 的参数优势让掉。具体开关随框架版本变，规划时应把「吸收后的每 token 字节 × 层数 × 并发 × 长度」写成显式账，而不是沿用 GQA 的 \\(2 h_{\\mathrm{kv}} d_k\\)。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,[t("MLA 能「头多、缓存小」，是因为头间差异放在"),e("strong",null,"权重"),t(" \\(W^{UK},W^{UV}\\) 的不同行块里，不放在随 \\(n\\) 增长的激活里。每 token 只有一份内容缓存，查询头读的是同一 \\(c^{KV}\\) 的不同线性读出。这与 GQA「不同组读不同缓存向量」相反：GQA 的压缩轴是头，组与组之间仍是独立激活；MLA 的压缩轴是 token 表示的秩。")],-1)),a[8]||(a[8]=e("p",null,"低秩假设是 \\(\\mathrm{rank}([K;V])\\) 受 \\(d_c\\) 限制。联合瓶颈比分别压缩 \\(K\\) 与 \\(V\\) 更强，参数和缓存都更省；若键方向与值内容几乎无关，这个瓶颈会先成为质量上限——那时应加宽 \\(d_c\\)，而不是再增加 KV 头数。加宽 \\(d_c\\) 线性增加缓存，是最直接的质量旋钮，对应 GQA 里加 \\(h_{\\mathrm{kv}}\\)。",-1)),(l(),o(i,null,{default:A(()=>[r(n,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E5%90%8C%E6%A0%B7%E7%9A%84%20KV%20%E6%98%BE%E5%AD%98%E9%97%AE%E9%A2%98%22%5D%20--%3E%20GQA%5B%22GQA%EF%BC%9A%E7%A0%8D%E5%A4%B4%E6%95%B0%20h_kv%22%5D%0A%20%20SUB%20--%3E%20MLA%5B%22MLA%EF%BC%9A%E7%A0%8D%E6%AF%8F%E6%9D%A1%E5%AE%BD%E5%BA%A6%EF%BC%8C%E5%A4%B4%E6%95%B0%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20GQA%20--%3E%20G1%5B%22%E7%BB%84%E9%97%B4%E4%BB%8D%E6%98%AF%E7%8B%AC%E7%AB%8B%E6%BF%80%E6%B4%BB%E7%BC%93%E5%AD%98%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E8%B4%A8%E9%87%8F%E9%9A%8F%E9%80%9A%E9%81%93%E6%95%B0%E4%B8%8B%E9%99%8D%22%5D%0A%20%20MLA%20--%3E%20M1%5B%22%E5%A4%B4%E9%97%B4%E5%B7%AE%E5%BC%82%E6%94%BE%E6%9D%83%E9%87%8D%E8%A1%8C%E5%9D%97%E9%87%8C%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E7%BC%93%E5%AD%98%E5%8F%AA%E6%9C%89%E6%AF%8F%20token%20%E4%B8%80%E4%BB%BD%20cKV%22%5D%0A%20%20G2%20--%3E%20KNOB%5B%22%E8%B4%A8%E9%87%8F%E6%97%8B%E9%92%AE%EF%BC%9A%E5%8A%A0%E5%A4%B4%20vs%20%E5%8A%A0%E5%AE%BD%20d_c%22%5D%0A%20%20M2%20--%3E%20KNOB%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=E('<p><span class="marginnote">降幅的数字实例：按文中 V2 的量级，MHA 每 token 每层要存 \\(2 \\times 128 \\times 128 = 32768\\) 个数；MLA 存 \\(c^{KV}\\) 的 512 加跨头共享的 RoPE 键 64，合计 576 个——约为原来的 1/57。存成 FP16 时就是每 token 每层从 64 KB 降到约 1.2 KB，乘上层数与并发数，这就是能多放几倍 batch 的来源。</span></p><p><span class="marginnote">吸收成立的前提是内容路径纯线性。中间插入非线性，或把 RoPE 打在展开后的满宽内容键上，就不能把 \\(W^{UK}\\) 从缓存路径里消掉。复现时若旋转打错位置，推理融合会悄悄算错相位，缓存形状却看起来仍是「压缩过的」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(d_c\\) 过窄时，先伤的是需要高精度复制的记忆：长数字、少见符号、精确实体，表现为检索式能力下降，而不是语言模型损失立刻崩盘。短生成、极大前填的工作负载上，MLA 的优势缩小——前填要付上投影或吸收后的大矩阵乘，decode 才收回内存流量。融合核写得差，墙钟甚至慢于调好的 GQA。</p><p>MLA 之上再做条数淘汰（SnapKV、H2O、StreamingLLM）是双重压缩：宽度已经窄了，再切条。收益必须单独量，汇点或 heavy hitter 在潜空间里的分数尺度与满宽 MHA 不同。KV 量化同样：对 \\(c^{KV}\\) 打 INT8 和对满宽 \\(K,V\\) 打 INT8，校准对象不是同一张量。不要把 V2 报告相对 MHA 的降幅，和量化论文相对 FP16 的降幅乘在一起当容量规划。</p><p><span class="marginnote">「压缩比不能相乘」是容量规划的高频事故：假设 MLA 降 4 倍、INT8 再降 2 倍，直觉说 8 倍，实际两者作用对象有重叠，真实降幅要实测。类比打折：一件衣服先打 5 折再参加「满减」，到手价不是原价的 25%，因为满减的基数是折后价——叠加优惠必须按实际账单算，显存账同理。</span></p><p><span class="marginnote">「开源权重能跑 MLA」不等于「服务图已经吸收」。用未融合的 Hugging Face 逐步生成去测延迟，测到的是 MHA 量级缓存加额外投影，不是报告里的推理效率。清单上应有：融合权重、RoPE 旁路、\\(c^{KV}\\) 布局、以及不按 GQA 核硬套。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLA 压缩的是每 token KV 的宽度：decode 缓存 \\(c^{KV}\\) 与小 RoPE 键，条数仍等于序列长。</li><li>上投影吸收是部署变换；不吸收就得不到作为服务卖点的缓存降幅。</li><li>压缩轴与 GQA 正交：后者少头，前者多头加窄潜变量。</li><li>并发与长生成吃的是带宽账单，每 token 字节下降才会变成更高的有效 batch。</li><li>\\(d_c\\) 是质量–缓存旋钮；过窄先伤精确记忆。</li><li>与条数淘汰、量化组合时要重新测量，不能把论文压缩比相乘。</li><li>出处：DeepSeek-AI, <em>DeepSeek-V2: A Strong, Economical, and Efficient Mixture-of-Experts Language Model</em>, 2024。对照 MHA / GQA 见 Vaswani et al., 2017；Shazeer, 2019；Ainslie et al., 2023。</li></ul>',9))])}const D=d(m,[["render",p]]);export{_ as __pageData,D as default};
